), comps AS (
 SELECT jsonb_build_object(''serie'',c->>''serie'',''categoria'',c->>''categoria'',
 ''atual'',CASE WHEN m.atual IS NOT NULL THEN m.atual WHEN jsonb_typeof(c->''atual'')=''object'' THEN (c->''atual'') || jsonb_build_object(''fonte'',''Snapshot inicial · coleta 26/09/2026; fonte ainda em conciliação'') ELSE ''null''::jsonb END,
 ''status'',CASE WHEN m.atual IS NOT NULL THEN ''notebook_em_conciliacao'' ELSE c->>''status'' END) AS item,n
 FROM b CROSS JOIN LATERAL jsonb_array_elements(b.payload->''comparacoes'') WITH ORDINALITY z(c,n)
 LEFT JOIN m ON m.serie=c->>''serie'' AND m.categoria=c->>''categoria''
)
SELECT b.payload || jsonb_build_object(
 ''meta'',(b.payload->''meta'') || jsonb_build_object(''origem'',''Notebook Business + fontes iniciais identificadas'',''totais_fontes'',jsonb_build_object(''resultados'',''vw_resultados · notebook, execução #7'',''eventos'',''Eventos no Brasil · notebook, execução #8''),''notebook_fontes'',(SELECT jsonb_agg(jsonb_build_object(''execucao'',id,''celula'',cell_id,''revisao'',cell_version,''coletado_em'',started_at) ORDER BY id) FROM r)),
 ''comparacoes'',(SELECT jsonb_agg(item ORDER BY n) FROM comps),
 ''conciliacao'',(SELECT jsonb_object_agg(status,n) FROM (SELECT item->>''status'' AS status,count(*) AS n FROM comps GROUP BY item->>''status'') q),
 ''totais_atuais'',jsonb_build_object(''resultados'',(SELECT x->''total'' FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->''rows'') x WHERE r.id=7 AND x->>''versao''=''DataGrip''),
 ''eventos'',(SELECT x->''eventos_cadastrados'' FROM r CROSS JOIN LATERAL jsonb_array_elements(r.result->''rows'') x WHERE r.id=8 AND x->>''ano''=''2025''))
) AS payload FROM b WHERE (SELECT count(*) FROM r)=7',139,'{"tipo":"ponte_web","ano":2025}','web-bqc-2025-payload') RETURNING id INTO c;
INSERT INTO estudo.web_destinos(ano,cell_id) VALUES(2025,c);
INSERT INTO estudo.notebooks(notebook_title,caderno_id,call_order,updated_by,source_key) VALUES('2026 — Saída para web',b,2026,139,'web-bqc-2026-section') RETURNING notebook_id INTO n;
INSERT INTO estudo.notebook_cells(notebook_id,cell_order,cell_type,lang,content,updated_by,origem,source_key) VALUES(n,1,'markdown','','Ponte para o snapshot 2026 v3 já usado pela web. Não recalcula números, datas de corte ou coortes. Para renovar a prévia, revise as consultas de origem e gere outro congelamento.',139,'{"tipo":"ponte_web"}','web-bqc-2026-note');
INSERT INTO estudo.notebook_cells(notebook_id,cell_order,cell_type,lang,content,updated_by,origem,source_key) VALUES(n,2,'code','sql','-- Ponte para a prévia 2026 já conferida: preserva números, cortes e coorte do snapshot v3.
-- A fonte original permanece identificada. Esta query não recalcula 2026 nem atualiza o corte.
-- Faça novas versões deste pacote no notebook depois de revisar as consultas e os congelamentos de origem.
SELECT payload || jsonb_build_object(''meta'',(payload->''meta'') || jsonb_build_object(''origem'',''Snapshot 2026 v3 preservado e congelado no notebook Business'')) AS payload
FROM estudo.web_bases WHERE ano=2026',139,'{"tipo":"ponte_web","ano":2026}','web-bqc-2026-payload') RETURNING id INTO c;
INSERT INTO estudo.web_destinos(ano,cell_id) VALUES(2026,c);
END;$seed$;
